-- Private conservation mechanics. Public restoration still requires the unavailable T06 remedy gate.
grant create on schema api,app_private to git_tutor_commands;
create table app_private.package_remedy_applications(remedy_reservation_id uuid primary key references app_private.remedy_reservations(id),movement_id uuid not null unique references app_private.entitlement_movements(id),command_id uuid not null,created_at timestamptz not null default now());
alter table app_private.package_remedy_applications enable row level security;grant select,insert on app_private.package_remedy_applications to git_tutor_commands;create policy commands_access on app_private.package_remedy_applications to git_tutor_commands using(true) with check(true);revoke all on app_private.package_remedy_applications from public,anon,authenticated,service_role,git_tutor_worker;
create trigger immutable_package_remedy_application before update or delete on app_private.package_remedy_applications for each row execute function app_private.reject_immutable_change();
create function app_private.package_consume_allocation_kernel(p_allocation_id uuid,p_credit_quanta bigint,p_context jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare a app_private.package_reservation_allocations%rowtype;r app_private.package_reservations%rowtype;previous app_private.entitlement_movements%rowtype;remainingq numeric;remainingv numeric;amount bigint;movement uuid;original uuid;begin
 select * into a from app_private.package_reservation_allocations where id=p_allocation_id;if a.id is null then raise exception 'NOT_FOUND';end if;select * into r from app_private.package_reservations where id=a.reservation_id;perform app_private.package_lock_purchase(r.purchase_id);select * into r from app_private.package_reservations where id=a.reservation_id for update;
 select * into previous from app_private.entitlement_movements where command_id=(p_context->>'command_id')::uuid and line_key='consume:'||a.id;
 if previous.id is not null then if previous.credit_quanta<>p_credit_quanta then raise exception 'IDEMPOTENCY_CONFLICT';end if;return jsonb_build_object('movement_id',previous.id,'consumed_credit_quanta',previous.credit_quanta,'consumed_value_minor',previous.value_minor);end if;
 select coalesce(sum((delta->>'reserved_credit_quanta')::numeric),0),coalesce(sum((delta->>'reserved_value_minor')::numeric),0) into remainingq,remainingv from app_private.entitlement_movements where allocation_id=a.id;
 if p_credit_quanta is null or p_credit_quanta<1 or p_credit_quanta>remainingq or r.state not in('reserved','partially_consumed') then raise exception 'INSUFFICIENT_ENTITLEMENT';end if;
 amount:=floor(remainingv*p_credit_quanta/remainingq)::bigint;select id into original from app_private.entitlement_movements where allocation_id=a.id and kind='reserve' order by recorded_at,id limit 1;
 movement:=app_private.package_append_movement(a.lot_id,'consume',jsonb_build_object('reserved_credit_quanta',-p_credit_quanta,'consumed_credit_quanta',p_credit_quanta,'reserved_value_minor',-amount,'consumed_value_minor',amount),jsonb_build_object('enrollment_id',r.enrollment_id,'reservation_id',r.id,'allocation_id',a.id,'original_movement_id',original,'credit_quanta',p_credit_quanta,'value_minor',amount,'from_bucket','reserved','to_bucket','consumed','customer_reason_code','qualified_service_consumption'),p_context,'consume:'||a.id);
 if amount>0 then perform finance_private.finance_post_balanced('package-consume:'||movement,'package_consumption',movement,'EGP',now(),jsonb_build_array(jsonb_build_object('account_code','deferred_package_obligation','learner_id',r.learner_id,'package_purchase_id',r.purchase_id,'lot_id',a.lot_id,'signed_minor',amount),jsonb_build_object('account_code','tuition_revenue','learner_id',r.learner_id,'package_purchase_id',r.purchase_id,'lot_id',a.lot_id,'signed_minor',-amount)),p_context);end if;
 update app_private.package_reservations set state=case when(select coalesce(sum((delta->>'reserved_credit_quanta')::numeric),0) from app_private.entitlement_movements where reservation_id=r.id)=0 then 'consumed' else 'partially_consumed' end,version=version+1,updated_at=now() where id=r.id;
 update app_private.package_purchases set version=version+1,updated_at=now() where id=r.purchase_id;
 return jsonb_build_object('movement_id',movement,'consumed_credit_quanta',p_credit_quanta,'consumed_value_minor',amount);
end $$;
create function app_private.package_consume_qualified(p_allocation_id uuid,p_decision_id uuid,p_context jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare enrollment uuid;qualification jsonb;begin
 select r.enrollment_id into enrollment from app_private.package_reservation_allocations a join app_private.package_reservations r on r.id=a.reservation_id where a.id=p_allocation_id;
 qualification:=app_private.package_assert_delivery_qualification(enrollment,p_decision_id);
 return app_private.package_consume_allocation_kernel(p_allocation_id,(qualification->>'credit_quanta')::bigint,p_context);
end $$;
create function app_private.package_reserve_remedy_kernel(p_consumption_id uuid,p_remedy_id uuid,p_credit_quanta bigint,p_value_minor bigint,p_mode text,p_context jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare movement app_private.entitlement_movements%rowtype;source finance_private.remedy_sources%rowtype;prior app_private.remedy_reservations%rowtype;usedq numeric;usedv numeric;result uuid;begin
 select * into movement from app_private.entitlement_movements where id=p_consumption_id and kind='consume';if movement.id is null then raise exception 'NOT_FOUND';end if;perform app_private.package_lock_purchase(movement.purchase_id);
 if p_remedy_id is null or p_credit_quanta is null or p_credit_quanta not between 0 and 9007199254740991 or p_value_minor is null or p_value_minor not between 0 and 9007199254740991 or(p_credit_quanta=0 and p_value_minor=0) or p_mode is null or p_mode not in('restoration','cash','account_credit') then raise exception 'VALIDATION_ERROR';end if;
 insert into finance_private.remedy_sources(consumption_id,learner_id,eligible_credit_quanta,eligible_value_minor) values(movement.id,movement.learner_id,movement.credit_quanta,movement.value_minor) on conflict(consumption_id) do nothing;
 select * into source from finance_private.remedy_sources where consumption_id=p_consumption_id for update;
 select * into prior from app_private.remedy_reservations where source_id=source.id and remedy_id=p_remedy_id;
 if prior.id is not null then if prior.credit_quanta<>p_credit_quanta or prior.value_minor<>p_value_minor or prior.mode<>p_mode then raise exception 'IDEMPOTENCY_CONFLICT';end if;return prior.id;end if;
 select coalesce(sum(credit_quanta),0),coalesce(sum(value_minor),0) into usedq,usedv from app_private.remedy_reservations where source_id=source.id and state in('reserved','consumed');
 if usedq+p_credit_quanta>source.eligible_credit_quanta or usedv+p_value_minor>source.eligible_value_minor then raise exception 'REMEDY_RESERVED';end if;
 insert into app_private.remedy_reservations(source_id,remedy_id,credit_quanta,value_minor,mode,state,command_id) values(source.id,p_remedy_id,p_credit_quanta,p_value_minor,p_mode,'reserved',(p_context->>'command_id')::uuid) returning id into result;return result;
end $$;
create function app_private.package_restore_kernel(p_remedy_reservation_id uuid,p_consumption_id uuid,p_context jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare consumption app_private.entitlement_movements%rowtype;lot app_private.package_lots%rowtype;remedy app_private.remedy_reservations%rowtype;source finance_private.remedy_sources%rowtype;movement uuid;destination text;begin
 select * into consumption from app_private.entitlement_movements where id=p_consumption_id and kind='consume';if consumption.id is null then raise exception 'NOT_FOUND';end if;perform app_private.package_lock_purchase(consumption.purchase_id);
 select * into lot from app_private.package_lots where id=consumption.lot_id for update;select * into source from finance_private.remedy_sources where consumption_id=p_consumption_id for update;select * into remedy from app_private.remedy_reservations where id=p_remedy_reservation_id for update;
 if remedy.id is null or remedy.source_id is distinct from source.id or remedy.mode<>'restoration' or remedy.credit_quanta<1 then raise exception 'REMEDY_RESERVED';end if;
 select movement_id into movement from app_private.package_remedy_applications where remedy_reservation_id=remedy.id;
 if movement is not null then return jsonb_build_object('movement_id',movement,'restored_credit_quanta',remedy.credit_quanta,'restored_value_minor',remedy.value_minor);end if;
 if remedy.state<>'reserved' then raise exception 'REMEDY_RESERVED';end if;destination:=case when lot.expires_at<=now() then 'expired' else 'available' end;
 movement:=app_private.package_append_movement(lot.id,'restore',jsonb_build_object('consumed_credit_quanta',-remedy.credit_quanta,'consumed_value_minor',-remedy.value_minor,destination||'_credit_quanta',remedy.credit_quanta,destination||'_value_minor',remedy.value_minor),jsonb_build_object('enrollment_id',consumption.enrollment_id,'reservation_id',consumption.reservation_id,'allocation_id',consumption.allocation_id,'original_movement_id',consumption.id,'credit_quanta',remedy.credit_quanta,'value_minor',remedy.value_minor,'from_bucket','consumed','to_bucket',destination,'customer_reason_code','approved_entitlement_restoration'),p_context,'restore:'||remedy.id);
 if remedy.value_minor>0 then perform finance_private.finance_post_balanced('package-restore:'||movement,'package_restoration',movement,'EGP',now(),jsonb_build_array(jsonb_build_object('account_code','tuition_revenue','learner_id',consumption.learner_id,'package_purchase_id',consumption.purchase_id,'lot_id',lot.id,'signed_minor',remedy.value_minor),jsonb_build_object('account_code','deferred_package_obligation','learner_id',consumption.learner_id,'package_purchase_id',consumption.purchase_id,'lot_id',lot.id,'signed_minor',-remedy.value_minor)),p_context);end if;
 insert into app_private.package_remedy_applications(remedy_reservation_id,movement_id,command_id) values(remedy.id,movement,(p_context->>'command_id')::uuid);update app_private.remedy_reservations set state='consumed' where id=remedy.id;update app_private.package_purchases set version=version+1,updated_at=now() where id=consumption.purchase_id;
 return jsonb_build_object('movement_id',movement,'restored_credit_quanta',remedy.credit_quanta,'restored_value_minor',remedy.value_minor);
end $$;
create function api.restore_package_credit(p_consumption_id uuid,p_credit_quanta bigint,p_remedy_id uuid,p_reason text,p_expected_version integer,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();m app_private.entitlement_movements%rowtype;p app_private.package_purchases%rowtype;context jsonb;remedy uuid;begin
 perform app_private.require_role(actor,'admin');select * into m from app_private.entitlement_movements where id=p_consumption_id and kind='consume';if m.id is null then raise exception 'NOT_FOUND';end if;
 if p_credit_quanta is null or p_credit_quanta not between 1 and 9007199254740991 or p_remedy_id is null or length(btrim(coalesce(p_reason,''))) not between 1 and 2000 then raise exception 'VALIDATION_ERROR';end if;
 context:=app_private.package_begin(actor,'restore_package_credit',jsonb_build_object('consumption_id',p_consumption_id,'credit_quanta',p_credit_quanta,'remedy_id',p_remedy_id,'reason',p_reason,'expected_version',p_expected_version),p_idempotency_key);if context->'replay_result'<>'null'::jsonb then return context->'replay_result';end if;
 p:=app_private.package_lock_purchase(m.purchase_id);if p.version is distinct from p_expected_version then raise exception 'VERSION_CONFLICT';end if;
 remedy:=app_private.package_reserve_remedy(m.id,p_remedy_id,p_credit_quanta,null,'restoration');
 -- The T06 gate above always refuses. A future integration must supply reviewed exact value and commit the qualified remedy atomically.
 raise exception 'DEPENDENCY_UNAVAILABLE';
end $$;
do $$ declare f record;begin for f in select p.oid::regprocedure::text as signature,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='app_private' and p.proname in('package_consume_allocation_kernel','package_consume_qualified','package_reserve_remedy_kernel','package_restore_kernel')) or(n.nspname='api' and p.proname='restore_package_credit') loop execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api' then execute format('grant execute on function %s to authenticated',f.signature);end if;end loop;end $$;
revoke create on schema api,app_private from git_tutor_commands;
notify pgrst,'reload schema';
